const CACHE='learn-everyday-v7';
const FILES=['./','./index.html','./guide.html','./guide.pdf','./styles.css?v=7','./glass.css?v=7','./vivid.css?v=3','./fonts.css','./app.js?v=7','./manifest.webmanifest','./modules/icons.js','./modules/diagrams.js','./modules/store.js','./modules/engine.js','./modules/audio.js','./data/english.js','./data/computer.js','./data/culture.js','./assets/hero-learning.svg','./assets/english.svg','./assets/computer.svg','./assets/culture.svg','./assets/icon.svg','./assets/icon-192.png','./assets/icon-512.png','./assets/apple-touch-icon.png',...Array.from({length:8},(_,i)=>'./assets/fonts/font-'+i+'.ttf')];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES)).then(()=>self.skipWaiting()));});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE&&k.startsWith('learn-everyday-')).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin)return;event.respondWith(fetch(event.request,{cache:'no-store'}).then(async response=>{if(response.ok){const cache=await caches.open(CACHE);cache.put(event.request,response.clone());}return response;}).catch(async()=>{const cached=await caches.match(event.request,{ignoreSearch:true});if(cached)return cached;if(event.request.mode==='navigate')return caches.match('./index.html');return new Response('غير متاح دون اتصال',{status:503,headers:{'Content-Type':'text/plain; charset=utf-8'}});}));});
